const tw = (value: string | undefined | null | false) => resolveClasses(value, componentUtilities);


type AccountUser = { id?:string; name?:string; email?:string; phone?:string; avatar?:string; role?:string };
type OrderRow    = { orderNumber:string; total:number; deliveryStatus:string; createdAt:string; paymentStatus?:string };
type Address     = { _id?:string; label?:string; recipientName?:string; phone?:string; line1:string; line2?:string; area?:string; city:string; district?:string; postalCode?:string; isDefault?:boolean };
type Quote       = { _id?:string; quoteNumber:string; subject:string; message?:string; status:string; quotedAmount?:number; adminResponse?:string; createdAt:string };
type Wallet      = { starPoints:number; storeCredit:number; transactions:Array<{_id?:string;type:string;amount:number;reference?:string;note?:string;createdAt:string}> };

function money(v:number|undefined){return `৳${Number(v||0).toLocaleString("en-BD")}`}
function badgeCls(s:string){
  const v=s.toLowerCase().replace(/\s/g,"_");
  if(v==="delivered") return "acc-badge acc-badge-green";
  if(v==="shipped")   return "acc-badge acc-badge-blue";
  if(v==="processing"||v==="confirmed"||v==="pending") return "acc-badge acc-badge-orange";
  if(v==="cancelled") return "acc-badge acc-badge-red";
  return "acc-badge acc-badge-gray";
}


