          <span className={utilities("qa-chevron", [3213, "[.acc-quote-scroll-list_:where(&).qa-chevron]:[font-size:9px]! [.acc-quote-scroll-list_:where(&).qa-chevron]:[color:#a0aec0]! [.acc-quote-scroll-list_:where(&).qa-chevron]:[flex-shrink:0]! [.acc-quote-scroll-list_:where(&).qa-chevron]:block! [.acc-quote-scroll-list_:where(&).qa-chevron]:[transition:transform_0.2s]!"])}>{open?"▲":"▼"}</span>
